# Parse all results to count Y and N classifications
import re

yes_count = 0
no_count = 0
yes_dialog_ids = []
unparsed = 0

for result in results:
    lines = result.strip().split('\n')
    for line in lines:
        line = line.strip()
        if ':Y' in line:
            # Extract dialog_id
            match = re.match(r'(\d+):Y', line)
            if match:
                yes_count += 1
                yes_dialog_ids.append(match.group(1))
            else:
                # Try other formats
                if line.endswith(':Y'):
                    parts = line.split(':')
                    if len(parts) >= 2:
                        yes_count += 1
                        yes_dialog_ids.append(parts[0].strip())
        elif ':N' in line:
            match = re.match(r'(\d+):N', line)
            if match:
                no_count += 1
            else:
                if line.endswith(':N'):
                    no_count += 1
        else:
            if line and not line.startswith('dialog_id') and not line.startswith('Format'):
                unparsed += 1

print(f"Classified as YES (poor driver behavior): {yes_count}")
print(f"Classified as NO: {no_count}")
print(f"Unparsed lines: {unparsed}")
